    """Shift the shades of tincture `src` to tincture `dst` (in the active palette).

    src_palette is the palette the fragment was drawn in: Sodacan's by default, a house's
    for that house's own charges.
    """
    target = _active["palette"]
    src_palette = src_palette or PALETTE
    if (src == dst and target is src_palette) or src not in src_palette or dst not in target:
        return fragment
    sh, sl, ss = _hls(src_palette[src])
    dh, dl, ds = _hls(target[dst])
    src_neutral = ss < 0.15

    def sub(m):
        col = m.group(0).lower()
        if len(col) == 4:
            col = "#" + "".join(ch * 2 for ch in col[1:])
        h, l, s = _hls(col)
        if src_neutral:
